using Microsoft.EntityFrameworkCore;
namespace FinSense;
public class Account { public int Id {get;set;} public string Name {get;set;}=""; public string Currency {get;set;}="CRC"; public bool Active {get;set;}=true; public string? Description {get;set;} }
public class Category { public int Id {get;set;} public string Name {get;set;}=""; public string Type {get;set;}="gasto"; public bool Active {get;set;}=true; }
public class Rule { public int Id {get;set;} public string Pattern {get;set;}=""; public string Match {get;set;}="contiene"; public string Type {get;set;}="gasto"; public int CategoryId {get;set;} public Category? Category {get;set;} public int Priority {get;set;}=100; public bool Active {get;set;}=true; }
public class Movement { public int Id {get;set;} public int AccountId {get;set;} public Account? Account {get;set;} public DateOnly Date {get;set;} public string Description {get;set;}=""; public string Type {get;set;}="gasto"; public decimal Amount {get;set;} public int? CategoryId {get;set;} public Category? Category {get;set;} public string Origin {get;set;}="manual"; public string? Reference {get;set;} public bool Active {get;set;}=true; public bool ManualCategory {get;set;} public int? RuleId {get;set;} public int? ImportId {get;set;} public DateTime CreatedAt {get;set;}=DateTime.UtcNow; public DateTime UpdatedAt {get;set;}=DateTime.UtcNow; }
public class ImportBatch {public int Id {get;set;} public int AccountId {get;set;} public string Filename {get;set;}=""; public int Accepted {get;set;} public int Rejected {get;set;} public int Duplicates {get;set;} public DateTime CreatedAt {get;set;}=DateTime.UtcNow;}
public class ChangeLog {public int Id {get;set;} public int MovementId {get;set;} public string Action {get;set;}=""; public DateTime At {get;set;}=DateTime.UtcNow;}
public class FinanceDb(DbContextOptions<FinanceDb> o):DbContext(o) {
 public DbSet<Account> Accounts=>Set<Account>(); public DbSet<Category> Categories=>Set<Category>(); public DbSet<Rule> Rules=>Set<Rule>(); public DbSet<Movement> Movements=>Set<Movement>(); public DbSet<ImportBatch> Imports=>Set<ImportBatch>(); public DbSet<ChangeLog> Changes=>Set<ChangeLog>();
 protected override void OnModelCreating(ModelBuilder m){m.Entity<Movement>().Property(x=>x.Amount).HasPrecision(18,2);m.Entity<Movement>().HasIndex(x=>new{x.AccountId,x.Date});m.Entity<Movement>().HasOne(x=>x.Account).WithMany().HasForeignKey(x=>x.AccountId).OnDelete(DeleteBehavior.Restrict);m.Entity<Movement>().HasOne(x=>x.Category).WithMany().HasForeignKey(x=>x.CategoryId).OnDelete(DeleteBehavior.Restrict);m.Entity<Rule>().HasOne(x=>x.Category).WithMany().HasForeignKey(x=>x.CategoryId).OnDelete(DeleteBehavior.Restrict);}
}
